void Solver::bump_var(int var, double coeff) {
    // Increment activity for the variable.
    activity[var] += var_inc * coeff;

    // Count bumps to limit how often we scan all variables.
    static unsigned long long bump_cnt = 0;
    ++bump_cnt;

    // Parameters for lazy overflow handling.
    constexpr double OVERFLOW_THR = 1e100;
    constexpr double RESCALE_FAC   = 1e-100;
    constexpr unsigned long long CHECK_PERIOD = 256ULL; // check every 256 bumps

    // Defer the costly full‑scale operation to periodic checks.
    if ((bump_cnt % CHECK_PERIOD) == 0) {
        if (activity[var] > OVERFLOW_THR || var_inc > OVERFLOW_THR) {
            for (int i = 1; i <= vars; ++i) activity[i] *= RESCALE_FAC;
            var_inc *= RESCALE_FAC;
        }
    }

    // Keep the VSIDS priority queue up‑to‑date.
    if (vsids.inHeap(var)) {
        vsids.update(var);
    }
}
